"use client";

// Operacional → Reportei → Automações: which clients have a report generated by
// itself, how often, and when it last ran. Each row opens the client's tab.

import { useEffect, useState } from "react";
import Link from "next/link";
import { useTranslations } from "next-intl";
import { ChevronRight, Zap } from "lucide-react";
import { EmptyState } from "@/components/dashboard/empty-state";
import { Skeleton } from "@/components/dashboard/skeleton";
import { ClientCode } from "@/components/operational/client-code";
import { showDate } from "@/lib/reportei/format";
import { cn } from "@/lib/utils";

interface Row {
  id: string;
  clientId: string;
  clientName: string;
  clientCode: string | null;
  frequency: "weekly" | "monthly";
  active: boolean;
  lastRunOn: string | null;
  lastError: string | null;
}

type State = { kind: "loading" } | { kind: "error" } | { kind: "ready"; rows: Row[] };

export default function ReporteiAutomationsPage() {
  const t = useTranslations("Operational.reportei.automationsPage");
  const tp = useTranslations("Operational.reportei.automationsPanel");
  const [state, setState] = useState<State>({ kind: "loading" });

  useEffect(() => {
    let alive = true;
    fetch("/api/operational/reportei/automations")
      .then(async (res) => {
        if (!alive) return;
        if (!res.ok) return setState({ kind: "error" });
        setState({ kind: "ready", rows: ((await res.json()) as { automations: Row[] }).automations });
      })
      .catch(() => alive && setState({ kind: "error" }));
    return () => {
      alive = false;
    };
  }, []);

  return (
    <>
      <div>
        <h1 className="text-2xl font-bold text-foreground">{t("title")}</h1>
        <p className="text-sm text-muted-foreground">{t("description")}</p>
      </div>

      {state.kind === "loading" && <Skeleton className="h-40" />}
      {state.kind === "error" && <EmptyState title={t("error")} className="min-h-40" />}
      {state.kind === "ready" && state.rows.length === 0 && <EmptyState title={t("emptyTitle")} hint={t("emptyHint")} className="min-h-40" />}
      {state.kind === "ready" && state.rows.length > 0 && (
        <ul className="divide-y divide-border overflow-hidden rounded-xl border border-border bg-card">
          {state.rows.map((r) => (
            <li key={r.id}>
              <Link href={`/operational/reportei/clientes/${r.clientId}`} className="flex items-center gap-3 px-4 py-3 transition-colors hover:bg-muted/40">
                <Zap className="h-4 w-4 shrink-0 text-primary" />
                <div className="min-w-0 flex-1">
                  <p className="flex flex-wrap items-center gap-x-1.5 text-sm font-medium text-foreground">
                    <ClientCode code={r.clientCode} />
                    <span className="truncate">{r.clientName}</span>
                  </p>
                  <p className="truncate text-xs text-muted-foreground">
                    {tp(`freq_${r.frequency}`)} · {r.lastRunOn ? t("lastRun", { date: showDate(r.lastRunOn) }) : t("neverRan")}
                    {r.lastError ? ` · ${tp(`error_${r.lastError}`)}` : ""}
                  </p>
                </div>
                <span className={cn("shrink-0 rounded-full px-2 py-0.5 text-[11px] font-medium", r.active ? "bg-emerald-500/15 text-emerald-500" : "bg-muted text-muted-foreground")}>
                  {r.active ? tp("statusOn") : tp("statusOff")}
                </span>
                <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" />
              </Link>
            </li>
          ))}
        </ul>
      )}
    </>
  );
}
